@Composable
fun RovaiMainShell(appViewModel:AppViewModel,servers:List<ServerProfile>){
    val selected by appViewModel.selectedProfile.collectAsStateWithLifecycle();val nav=rememberNavController()
    NavHost(nav,startDestination="workbench"){
        composable("workbench"){RovaiWorkspaceScreen(selected?:servers.firstOrNull(),onServers={nav.navigate("servers")})}
        composable("servers"){ServerListScreen(servers,selected?.id,appViewModel::selectServer,appViewModel::deleteServer,{nav.navigate("editor")},{nav.navigate("editor?serverId=$it")},{nav.popBackStack()})}
        composable("editor?serverId={serverId}",arguments=listOf(navArgument("serverId"){type=NavType.StringType;nullable=true;defaultValue=null})){ServerEditorScreen(onDone={nav.popBackStack()})}
    }
}
@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun RovaiWorkspaceScreen(profile:ServerProfile?,onServers:()->Unit,model:RovaiWorkspaceViewModel=hiltViewModel()){
    val state by model.state.collectAsStateWithLifecycle();var tab by rememberSaveable{mutableIntStateOf(0)};val lifecycle=LocalLifecycleOwner.current
    var board by remember{mutableStateOf<JsonObject?>(null)};var newConversation by remember{mutableStateOf(false)};var engineering by remember(profile){mutableStateOf(false)};var settingsPage by remember(profile){mutableStateOf<String?>(null)};var editingMember by remember(profile){mutableStateOf<JsonObject?>(null)};var creatingMember by remember(profile){mutableStateOf(false)};var notifications by remember(profile){mutableStateOf(false)}
    val incomingLink by app.codeg.android.core.common.RovaiDeepLinkBus.pending.collectAsStateWithLifecycle()
    var linkIssue by remember(profile){mutableStateOf<String?>(null)}
    LaunchedEffect(profile){model.bind(profile)}
    LaunchedEffect(incomingLink,state.connected,state.busy,state.pending){
        val link=incomingLink?:return@LaunchedEffect;if(!state.connected||state.busy||state.pending!=null)return@LaunchedEffect
        val generation=model.connectionGeneration
        try {
            var threadTarget:String?=null;var canvasTarget:JsonObject?=null;var nextTab:Int?=null;var pane:String?=null
            when(link.kind){
                "thread"->{threadTarget=link.value;nextTab=0}
                "mission"->{val mission=model.query(RovaiOperation.MISSIONS_GET,buildJsonObject{put("missionId",link.value)}).coreObject();threadTarget=mission.coreText("threadId");require(!threadTarget.isNullOrBlank()){"使命对话不存在"};nextTab=1}
                "canvas"->{canvasTarget=model.query(RovaiOperation.CANVAS_BOARDS_GET,buildJsonObject{put("boardId",link.value)}).coreObject()["board"] as? JsonObject;require(canvasTarget!=null){"画布不存在"};nextTab=3}
                "tab"->{nextTab=when(link.value.lowercase()){ "chats","threads"->0;"missions"->1;"members"->2;"canvas","canvases"->3;"settings"->4;else->throw IllegalArgumentException("此旧版入口请从当前工作区导航打开")}}
                "settings"->{nextTab=4;pane=when(link.value.lowercase()){ "appearance"->"appearance";"agents","runtime"->"runtime";"skills","experts"->"skills";"mcp"->"mcp";"notifications"->"notifications";"quickmessages"->"quickMessages";else->throw IllegalArgumentException("该设置入口尚未映射，请从设置页打开")}}
                else->throw IllegalArgumentException("这是原Codeg对象链接，请先导入原会话或从工程列表打开；不会将旧编号当作新对话。")
            }
            if(model.connectionGeneration!=generation||app.codeg.android.core.common.RovaiDeepLinkBus.pending.value!=link)return@LaunchedEffect
            notifications=false;engineering=false;settingsPage=pane;board=canvasTarget;nextTab?.let{tab=it};model.openThread(threadTarget);linkIssue=null
        }catch(cancelled:kotlinx.coroutines.CancellationException){throw cancelled}catch(error:Exception){if(model.connectionGeneration==generation)linkIssue=error.message}
        app.codeg.android.core.common.RovaiDeepLinkBus.consume(link)
    }
    DisposableEffect(lifecycle,model){val observer=LifecycleEventObserver{_,event->if(event==Lifecycle.Event.ON_START)model.foreground(true)else if(event==Lifecycle.Event.ON_STOP)model.foreground(false)};lifecycle.lifecycle.addObserver(observer);onDispose{lifecycle.lifecycle.removeObserver(observer);model.foreground(false)}}
    BackHandler(enabled=settingsPage!=null){settingsPage=null}
    BackHandler(enabled=!engineering&&settingsPage==null&&(state.selectedThread!=null||board!=null)){if(board!=null)board=null else model.openThread(null)}
    val titles=listOf("对话","使命","队员","画布","设置");val icons=listOf(Icons.Outlined.Forum,Icons.Outlined.Flag,Icons.Outlined.Groups,Icons.Outlined.Map,Icons.Outlined.Settings)
    Scaffold(containerColor=Color.Transparent,topBar={TopAppBar(title={Text(state.thread?.get("thread").coreObject().coreText("title").ifEmpty{board?.coreText("name")?:profile?.name?:"Rovai Workbench"})},navigationIcon={if(state.selectedThread!=null||board!=null)IconButton(onClick={if(board!=null)board=null else model.openThread(null)}){Icon(Icons.AutoMirrored.Outlined.ArrowBack,null)}},actions={IconButton(enabled=state.connected,onClick={notifications=true}){Icon(Icons.Outlined.Notifications,"提醒")};if(tab==2&&state.selectedThread==null)IconButton(enabled=state.pending==null&&state.connected,onClick={creatingMember=true}){Icon(Icons.Outlined.PersonAdd,"新建队员")};if(state.selectedThread!=null)IconButton(onClick={engineering=true}){Icon(Icons.Outlined.Folder,"工程")};IconButton(onClick=onServers){Icon(Icons.Outlined.Dns,"服务器")};IconButton(onClick=model::refreshNow,enabled=state.connected){Icon(Icons.Outlined.Refresh,"刷新")};if(tab==0&&state.selectedThread==null)IconButton(onClick={newConversation=true},enabled=state.connected&&state.pending==null){Icon(Icons.Outlined.Add,"新对话")}},colors=TopAppBarDefaults.topAppBarColors(containerColor=Color.Transparent))},bottomBar={if(state.selectedThread==null&&board==null)NavigationBar(containerColor=CodegTheme.colors.bgElevated){titles.forEachIndexed{index,title->NavigationBarItem(selected=tab==index,onClick={tab=index},icon={Icon(icons[index],title)},label={Text(title)})}}}){padding->Column(Modifier.fillMaxSize().padding(padding)){
        linkIssue?.let{Text(it,color=CodegTheme.colors.danger,modifier=Modifier.padding(12.dp))}
        if(state.error!=null)Text(state.error!!,color=CodegTheme.colors.danger,modifier=Modifier.padding(12.dp))
        if(state.pending!=null)Row(Modifier.fillMaxWidth().padding(8.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){Text("原操作待核对",Modifier.weight(1f));TextButton(onClick=model::reconcile,enabled=!state.busy){Text("核对")};TextButton(onClick=model::retry,enabled=!state.busy){Text("重试原操作")}}
        if(!state.connected){Column(Modifier.padding(24.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){Text("连接 ${profile?.name?:"工作区"}",style=MaterialTheme.typography.titleLarge);Text("连接后使用服务器中的对话、使命、队员和工程。",color=CodegTheme.colors.textSecondary);Button(onClick=model::authenticate,enabled=!state.busy){Text(if(state.busy)"正在连接…" else "连接工作区")};TextButton(onClick=onServers){Text("管理服务器")}}}
        else if(engineering&&state.selectedThread!=null)RovaiEngineeringScreen(model,state.selectedThread!!,state.pending!=null){engineering=false}
        else if(state.selectedThread!=null)RovaiThreadScreen(model,state)
        else if(board!=null)RovaiNativeCanvas(model,board!!)
        else when(tab){
            0->LazyColumn(Modifier.fillMaxSize(),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
                val quick=state.navigation["quickChat"].coreObject()["recentThreads"].coreArray();if(quick.isNotEmpty()){item{Text("快速对话",style=MaterialTheme.typography.titleSmall)};items(quick,key={"quick:"+it.coreText("id")}){RovaiThreadRow(it){model.openThread(it.coreText("id"))}}}
                state.navigation["projects"].coreArray().forEach{project->item{Text(project.coreText("name"),style=MaterialTheme.typography.titleSmall)};items(project["recentThreads"].coreArray(),key={project.coreText("projectKey")+it.coreText("id")}){RovaiThreadRow(it){model.openThread(it.coreText("id"))}};item{RovaiMoreThreads(model,project.coreText("projectPath"),project.coreLong("totalCount").toInt(),project["recentThreads"].coreArray().map{it.coreText("id")}.toSet())}}
            }
            1->LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){items(state.missions,key={it.coreText("missionId")}){mission->GlassRow(Modifier.fillMaxWidth()){Text(mission.coreText("title"),style=MaterialTheme.typography.titleMedium);Text(mission.coreText("status"),color=CodegTheme.colors.textSecondary);Text(mission.coreText("description"),maxLines=3);Row{TextButton(onClick={model.openThread(mission.coreText("threadId"))}){Text("打开对话")};if((mission["startAvailable"] as? JsonPrimitive)?.booleanOrNull==true)TextButton(enabled=state.pending==null,onClick={model.command(RovaiOperation.MISSIONS_START,buildJsonObject{put("missionId",mission.coreText("missionId"))})}){Text("开始使命")}}}}}
            2->LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){items(state.members,key={it.coreText("agentId")}){member->GlassRow(Modifier.fillMaxWidth().clickable{editingMember=member}){Text(member.coreText("displayName"),style=MaterialTheme.typography.titleMedium);Text(member.coreText("teamRole"),color=CodegTheme.colors.textSecondary);Text(member.coreText("professionalResponsibilities"));val readiness=member["runtimeReadiness"].coreObject();Text(readiness.coreText("status"),style=MaterialTheme.typography.labelMedium,color=CodegTheme.colors.accent);RovaiMemberLifecycle(model,member)}}}
            3->LazyColumn(contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){items(state.boards,key={it.coreText("id")}){canvas->GlassRow(Modifier.fillMaxWidth().clickable{board=canvas}){Icon(Icons.Outlined.Map,null,tint=CodegTheme.colors.textSecondary);Text(canvas.coreText("name").ifEmpty{"未命名画布"},style=MaterialTheme.typography.titleMedium);Text(canvas.coreText("description"),color=CodegTheme.colors.textSecondary)}}}
            4->if(settingsPage=="quickMessages")RovaiMessageLibrary(model)else if(settingsPage=="skills")RovaiSkillSettings(model)else if(settingsPage=="mcp")RovaiMcpSettings(model)else if(settingsPage=="appearance")RovaiAppearanceSettings()else if(settingsPage=="runtime")RovaiRuntimeSettings(model)else if(settingsPage=="notifications")RovaiNotificationSettings(model)else Column(Modifier.padding(24.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){GlassRow(Modifier.fillMaxWidth().clickable(onClick=onServers)){Text("服务器");Text(profile?.baseUrl?:"",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="notifications"}){Text("提醒");Text("会话、使命、任务和提醒状态",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="runtime"}){Text("智能体、模型和权限");Text("按队员配置实际Host支持的运行参数",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="appearance"}){Text("外观");Text("沿用Codeg原生主题、色彩和预览",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="skills"}){Text("技能与专家库");Text("预览、安装和队员选择",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="quickMessages"}){Text("快捷消息和标签");Text("管理全局可复用内容",color=CodegTheme.colors.textSecondary)};GlassRow(Modifier.fillMaxWidth().clickable{settingsPage="mcp"}){Text("MCP连接");Text("配置连接和队员访问权限",color=CodegTheme.colors.textSecondary)};TextButton(onClick=model::logout){Text("退出当前连接")}}
        }
    }}
    if(notifications)Dialog(onDismissRequest={notifications=false},properties=DialogProperties(usePlatformDefaultWidth=false,dismissOnBackPress=false,dismissOnClickOutside=false)){Surface(Modifier.fillMaxSize(),color=CodegTheme.colors.bgElevated){RovaiNotificationInbox(model){notifications=false}}}
    if(creatingMember||editingMember!=null)RovaiMemberEditor(model,editingMember){creatingMember=false;editingMember=null}
    if(newConversation)RovaiNewThreadDialog(state,onDismiss={newConversation=false},onCreate={name,path,ids,lead,mode->model.execute(RovaiOperation.THREADS_CREATE,buildJsonObject{put("commandId",java.util.UUID.randomUUID().toString());put("name",name);put("workspace",path?.let{buildJsonObject{put("projectPath",it)}}?:JsonNull);put("memberAgentIds",JsonArray(ids.map(::JsonPrimitive)));put("defaultLeadAgentId",lead);put("collaborationMode",mode);put("activationState","active")});newConversation=false})
}
