    Column(Modifier.fillMaxSize()){inputIssue?.let{Text(it,color=CodegTheme.colors.danger,modifier=Modifier.padding(12.dp))};LazyColumn(Modifier.weight(1f),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{TextButton(enabled=bodyReady&&state.pending==null&&!state.busy,onClick={library=true}){Text("快捷消息和标签")};TextButton(onClick={coroutine.launch{try{if(bodyReady)model.saveBody(owner,model.publicBody(text,recipients,inputRevision));privateChat=true}catch(error:Exception){inputIssue=error.message}}}){Text("队员私聊")};RovaiAttachmentPicker(model,state.selectedThread!!,buildJsonObject{put("kind","camp")},0,state.pending!=null||state.busy||!state.publicSourcesReady);state.publicSources.forEach{source->Row{Text("附件 · "+source.coreText("displayName"),Modifier.weight(1f));TextButton(enabled=state.pending==null&&!state.busy,onClick={model.removePublicSource(source.coreText("id"))}){Text("移除")}};RovaiThreadControls(model,state);thread?.get("agentRuns").coreArray().forEach{run->key(run.coreText("id")){RovaiExecutionHistory(model,state.selectedThread!!,run,thread?.get("executionEvidence").coreArray())}}};items(thread?.get("messages").coreArray(),key={it.coreText("id")}){message->GlassRow(Modifier.fillMaxWidth(),selected=message.coreText("authorType")=="user"){Text(message.coreText("authorDisplayName").ifEmpty{if(message.coreText("authorType")=="user")"你" else message.coreText("authorId")},style=MaterialTheme.typography.labelMedium,color=CodegTheme.colors.textSecondary);MarkdownContent(message.coreText("body"));RovaiMessageArtifacts(model,state.selectedThread!!,message);RovaiRuntimeImageGallery(model,state.selectedThread!!,rovaiImageGroups(thread?:buildJsonObject{},message))}};items(rovaiOrphanImages(thread?:buildJsonObject{}),key={"images:"+it.coreText("agentRunId")+":"+it.coreLong("executionEpoch")}){group->GlassRow{RovaiRuntimeImageGallery(model,state.selectedThread!!,listOf(group))}};items(thread?.get("agentRuns").coreArray(),key={"run:"+i