        Row(Modifier.fillMaxWidth().imePadding().padding(12.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedTextField(value=text,onValueChange={if(model.state.value.pending==null&&!model.state.value.busy&&text!=it){text=it;inputRevision++;model.rememberBody(owner,model.publicBody(text,recipients,inputRevision))}},modifier=Modifier.weight(1f),maxLines=6,placeholder={Text("发送消息…")},enabled=bodyReady&&state.pending==null&&!state.busy);FilledIconButton(onClick={val frozenText=text;val frozenRecipients=recipients;val frozenThread=state.selectedThread!!;val document=model.publicBody(text,recipients,inputRevision);coroutine.launch{try{model.saveBody(owner,document);model.send(frozenText,frozenRecipients,document,frozenThread)}catch(error:Exception){inputIssue=error.message}}},enabled=text.isNotBlank()&&state.pending==null&&!state.busy&&state.publicSourcesReady&&bodyReady&&inputIssue==null){Icon(Icons.Outlined.Send,"发送")}}
